<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('company'); $data=db_load(); $company=db_company_by_user($data,(int)$_SESSION['user_id']); $cid=(int)($company['id']??0); $allowed=['Under Review','Shortlisted','Interview','Selected','Rejected']; $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $aid=(int)($_POST['application_id']??0);$new=$_POST['status']??'';if(in_array($new,$allowed,true)){foreach($data['applications'] as &$a){$i=db_internship($data,(int)$a['internship_id']);if((int)$a['id']===$aid&&$i&&(int)$i['company_id']===$cid)$a['status']=$new;}unset($a);if(db_save($data))$message='Application status updated.';}} $rows=[];foreach($data['applications'] as $a){$i=db_internship($data,(int)$a['internship_id']);if(!$i||(int)$i['company_id']!==$cid)continue;$s=null;foreach($data['students'] as $st)if((int)$st['id']===(int)$a['student_id'])$s=$st;$u=$s?db_user($data,(int)$s['user_id']):null;if(!$u)continue;$a['student_name']=$u['name'];$a['email']=$u['email'];$a['skills']=$s['skills']??'';$a['college']=$s['college']??'';$a['title']=$i['title'];$rows[]=$a;}usort($rows,fn($a,$b)=>strcmp($b['applied_at'],$a['applied_at'])); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Applicants · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'company_nav.php'; ?><main class="dashboard"><div class="page-heading"><div><p class="eyebrow">CANDIDATE PIPELINE</p><h1>Applicants.</h1><p>Review candidates and keep their application status current.</p></div></div><?php if($message): ?><div class="alert success"><?=e($message)?></div><?php endif; ?><div class="table-card"><table><thead><tr><th>Student</th><th>Internship</th><th>Skills</th><th>Applied</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="empty">No applicants yet.</td></tr><?php else: foreach($rows as $r): ?><tr><td><strong><?=e($r['student_name'])?></strong><br><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><?=e($r['skills']?:'Not added')?></td><td><?=e(date('d M Y',strtotime($r['applied_at'])))?></td><td><span class="status <?=e(status_class($r['status']))?>"><?=e($r['status'])?></span></td><td><form method="POST" class="inline-form"><input type="hidden" name="application_id" value="<?=$r['id']?>"><select name="status"><?php foreach($allowed as $s): ?><option <?=$r['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select><button class="btn small">Save</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></main></body></html>
